begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('schedule_a')::uuid),(md5('schedule_b')::uuid);
insert into profiles(id,display_name) values(md5('schedule_a')::uuid,'A'),(md5('schedule_b')::uuid,'B');
insert into account_preferences(owner_id) values(md5('schedule_a')::uuid),(md5('schedule_b')::uuid);
create function pg_temp.rotation(n integer) returns uuid language plpgsql security invoker as $$
declare root uuid;day uuid;
begin
 insert into public.programs(owner_id,name,cycle_length,objective,duration_rotations) values(auth.uid(),'Progression rotation '||n,n,'hypertrophy',1) returning id into root;
 for i in 1..n loop
 insert into public.program_days(owner_id,program_id,cycle_length,cycle_position,name,is_rest_day) values(auth.uid(),root,n,i,'Workout '||i,i%2=0) returning id into day;
 if i%2<>0 then insert into public.program_slots(owner_id,program_day_id,position,movement_pattern_id,exercise_id,target_sets,target_reps_min,target_reps_max,required_exercise_type,primary_muscle_id) values(auth.uid(),day,1,(select id from public.movement_patterns where slug='horizontal_push'),(select id from public.exercises where slug='barbell_bench_press'),2,8,12,'compound',(select id from public.muscle_groups where slug='pectorals'));end if;
 end loop;return public.snapshot_program(root);
end $$;
create function pg_temp.finish_day(v uuid,d int,nonce text) returns uuid language plpgsql security invoker as $$
declare w uuid;m uuid;e uuid;s public.workout_sets;
begin
 w:=public.start_program_workout(v,d,md5(nonce)::uuid);
 select id into m from public.workout_movements where workout_session_id=w and owner_id=auth.uid() limit 1;
 e:=public.select_program_exercise(m,(select id from public.exercises where slug='barbell_bench_press'),null,gen_random_uuid());
 for s in select * from public.workout_sets where workout_exercise_id=e and owner_id=auth.uid() order by position loop
 perform public.log_workout_set(p_item=>e,p_id=>s.id,p_operation=>'save',p_revision=>s.revision,p_mutation=>gen_random_uuid(),p_reps=>12,p_weight=>50,p_type=>'working',p_completed=>true);
 end loop;
 perform public.end_workout(w,'completed');return w;
end $$;
select ok(not has_function_privilege('anon','public.program_progression_evidence(uuid)','EXECUTE'),'anonymous evidence denied');
select ok(not has_function_privilege('anon','public.program_saved_progress(uuid,uuid)','EXECUTE'),'anonymous saved progress denied');
select ok(not has_function_privilege('service_role','public.program_adherence(uuid)','EXECUTE'),'service-role bypass denied');

create function pg_temp.date_session(w uuid,d date) returns void language plpgsql as $$
begin
 update public.workout_sessions set started_at=d::timestamp+interval '10 hours',finished_at=d::timestamp+interval '11 hours',effective_finished_at=d::timestamp+interval '11 hours',last_activity_at=d::timestamp+interval '10 hours 59 minutes',activity_evidence_at=d::timestamp+interval '10 hours 59 minutes' where id=w;
end $$;

create function pg_temp.enroll(v uuid) returns void language plpgsql security invoker as $$
declare a public.program_assignments;begin
 select * into a from public.program_assignments where owner_id=auth.uid() and state='active';
 if a.id is null then perform public.program_lifecycle('start',gen_random_uuid(),null,0,v,(clock_timestamp() at time zone (select scheduling_timezone from public.account_preferences where owner_id=auth.uid()))::date,(select scheduling_timezone from public.account_preferences where owner_id=auth.uid()));
 elsif a.source_version_id<>v then perform public.program_lifecycle('switch',gen_random_uuid(),a.id,a.lifecycle_revision,v,(clock_timestamp() at time zone (select scheduling_timezone from public.account_preferences where owner_id=auth.uid()))::date,(select scheduling_timezone from public.account_preferences where owner_id=auth.uid()));end if;
end $$;

set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('schedule_a')::uuid,'role','authenticated')::text,true);
select ok(valid_scheduling_timezone('America/New_York'),'IANA timezone supported');
select ok(valid_scheduling_timezone('UTC'),'explicit UTC fallback supported');
select ok(not valid_scheduling_timezone('PST'),'ambiguous abbreviation rejected');
select ok(not valid_scheduling_timezone('Imaginary/City'),'unknown timezone rejected');
select set_config('body_test.v',pg_temp.rotation(7)::text,true);
reset role;
insert into program_assignments(owner_id,program_id,cycle_length,source_version_id) select md5('schedule_a')::uuid,program_id,7,id from program_versions where id=current_setting('body_test.v')::uuid;
set local role authenticated;
select set_config('body_test.w',start_program_workout(current_setting('body_test.v')::uuid,1,md5('schedule_start')::uuid)::text,true);
select set_config('body_test.a',(select program_assignment_id::text from workout_sessions where id=current_setting('body_test.w')::uuid),true);
select is(program_schedule()->>'configured','false','legacy/unconfigured assignment has no fabricated calendar');
select throws_ok($$select configure_program_schedule(current_setting('body_test.a')::uuid,current_date-1,'UTC',md5('bad_past')::uuid)$$,'22023',null,'past initialization rejected');
select throws_ok($$select configure_program_schedule(current_setting('body_test.a')::uuid,current_date,'Mars/Base',md5('bad_zone')::uuid)$$,'22023',null,'invalid zone rejected');
select lives_ok($$select configure_program_schedule(current_setting('body_test.a')::uuid,current_date,'UTC',md5('configure_a')::uuid)$$,'explicit future calendar initialization');
select lives_ok($$select configure_program_schedule(current_setting('body_test.a')::uuid,current_date,'UTC',md5('configure_a')::uuid)$$,'configuration retry is idempotent');
select throws_ok($$select configure_program_schedule(current_setting('body_test.a')::uuid,current_date+1,'UTC',md5('configure_a')::uuid)$$,'23514',null,'configuration nonce is payload-bound');
select throws_ok($$select configure_program_schedule(current_setting('body_test.a')::uuid,current_date,'Europe/London',md5('other_config')::uuid)$$,'23514',null,'competing configuration cannot rewrite existing calendar');
select end_workout(current_setting('body_test.w')::uuid,'abandoned');
reset role;
update program_assignments set schedule_start_date=current_date-20 where id=current_setting('body_test.a')::uuid;
set local role authenticated;
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,1,'missed dates never advance initial workout');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'dueOn')::date,current_date-20,'original due date retained after a week away');
select is(program_schedule(),program_schedule(),'page views produce stable projections');
select is((program_schedule()->'next'->>'recommendedOn')::date,current_date,'overdue workout carried to current local date');
select is((select count(*)::int from jsonb_array_elements(program_schedule(null,current_date-20,7)->'events')e where e->>'status'='overdue'),1,'historical missed due date remains visible');
select ok(not exists(select 1 from jsonb_array_elements(program_schedule()->'events')e where e->>'kind'='rest' and e->>'status'='overdue'),'planned rest never marked overdue');
select is((select count(*)::int from workout_sessions where program_assignment_id=current_setting('body_test.a')::uuid),1,'calendar reads never create sessions');
select throws_ok($$select program_schedule(null,current_date,43)$$,'22023',null,'projection work bounded to 42 dates');
select throws_ok($$select program_schedule(null,'infinity',7)$$,'22023',null,'unbounded dates rejected');
reset role;
update program_assignments set schedule_start_date=current_date-1 where id=current_setting('body_test.a')::uuid;
set local role authenticated;
select is((program_schedule()->'next'->>'position')::int,1,'one missed workout day remains pending');
reset role;
update program_assignments set schedule_start_date=current_date-2 where id=current_setting('body_test.a')::uuid;
set local role authenticated;
select is((program_schedule()->'next'->>'position')::int,1,'two consecutive missed days do not consume workouts or stack rest');
reset role;
update program_assignments set schedule_start_date=current_date-7 where id=current_setting('body_test.a')::uuid;
set local role authenticated;
select is((program_schedule()->'next'->>'position')::int,1,'return after a week recommends original required workout');
reset role;
update program_assignments set schedule_start_date=current_date-20 where id=current_setting('body_test.a')::uuid;
set local role authenticated;
select set_config('body_test.full',pg_temp.finish_day(current_setting('body_test.v')::uuid,1,'full_late')::text,true);
reset role;
select pg_temp.date_session(current_setting('body_test.full')::uuid,current_date-3);
set local role authenticated;
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,3,'full saved workout resolves its exact prescribed position');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'dueOn')::date,current_date-1,'rest projected relative to actual late completion');
select is((program_schedule()->'next'->>'recommendedOn')::date,current_date,'extra rest does not accumulate mandatory rest days');
select is((select count(*)::int from jsonb_array_elements(program_schedule(null,current_date-20,21)->'events')e where e->>'date'=(current_date-20)::text and e->>'status'='overdue'),1,'late actual completion never rewrites original overdue date');
select is((select count(*)::int from jsonb_array_elements(program_schedule(null,current_date-3,7)->'events')e where e->>'date'=(current_date-3)::text and e->>'status'='completed'),1,'completion shown on actual local date');
select is((select count(*)::int from jsonb_array_elements(program_schedule(null,current_date-3,7)->'events')e where e->>'date'=(current_date-2)::text and e->>'status'='planned_rest'),1,'recovery position shown after actual training');
select is((program_adherence()->>'nextPosition')::int,3,'adherence uses same scheduling cursor');
select set_config('body_test.next',start_program_workout(current_setting('body_test.v')::uuid,3,md5('partial_scheduled')::uuid)::text,true);
select set_config('body_test.m',(select id::text from workout_movements where workout_session_id=current_setting('body_test.next')::uuid),true);
select set_config('body_test.e',select_program_exercise(current_setting('body_test.m')::uuid,(select id from exercises where slug='barbell_bench_press'),null,md5('partial_scheduled_pick')::uuid)::text,true);
select log_workout_set(p_item=>current_setting('body_test.e')::uuid,p_id=>(select id from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid order by position limit 1),p_operation=>'save',p_revision=>0,p_mutation=>md5('partial_scheduled_set')::uuid,p_reps=>9,p_weight=>50,p_type=>'working',p_completed=>true);
select end_workout(current_setting('body_test.next')::uuid,'completed');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,3,'partial training holds the required position');
select is((program_adherence()->>'nextPosition')::int,3,'partial adherence reconciled with scheduled policy');
select is((select count(*)::int from jsonb_array_elements(program_schedule()->'events')e where e->>'status'='recorded_partial'),1,'partial is recorded training, never false completion');
select is((program_schedule()->'next'->>'recommendedOn')::date,current_date+2,'partial recorded training also informs recovery');
reset role;
-- The first resolution was on time; a later independent repeat is not a missed occurrence.
update program_assignments set schedule_start_date=current_date-3 where id=current_setting('body_test.a')::uuid;
update workout_sessions set schedule_due_on=current_date-3 where id=current_setting('body_test.full')::uuid;
set local role authenticated;
select set_config('body_test.repeat',pg_temp.finish_day(current_setting('body_test.v')::uuid,1,'repeated_resolved')::text,true);
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,3,'repeating a resolved workout cannot consume the pending position');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'dueOn')::date,current_date-1,'repeated training does not erase the outstanding original due date');
select ok(not exists(select 1 from jsonb_array_elements(program_schedule(null,current_date-3,7)->'events')e where e->>'status'='overdue' and (e->>'position')::int=1),'late repeat does not retroactively mark an on-time original workout overdue');
select set_config('body_test.retry',start_program_workout(current_setting('body_test.v')::uuid,3,md5('empty_retry')::uuid)::text,true);
select is((select source_rotation from workout_sessions where id=current_setting('body_test.retry')::uuid),0,'partial retry retains rotation identity');
select is(start_program_workout(current_setting('body_test.v')::uuid,3,md5('empty_retry')::uuid),current_setting('body_test.retry')::uuid,'duplicate start binds once');
select end_workout(current_setting('body_test.retry')::uuid,'completed');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,3,'empty completion never advances');
select set_config('body_test.fulld3',pg_temp.finish_day(current_setting('body_test.v')::uuid,3,'full_d3')::text,true);
select set_config('body_test.ooo',pg_temp.finish_day(current_setting('body_test.v')::uuid,7,'out_of_order_d7')::text,true);
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,5,'out-of-order completion does not discard outstanding position');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'completedRotations')::int,0,'out-of-order gap prevents full rotation');
select set_config('body_test.fulld5',pg_temp.finish_day(current_setting('body_test.v')::uuid,5,'full_d5')::text,true);
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'readyOn')::date,current_date+2,'already resolved out-of-order workout does not duplicate a future recovery block');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'rotation')::int,1,'full variable-length rotation wraps independently of calendar week');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'completedRotations')::int,1,'full rotation requires all required positions');
select is(program_schedule(current_setting('body_test.a')::uuid)->'next','null'::jsonb,'fixed-duration calendar stops at completed rotation target');
select throws_ok($$update workout_sessions set schedule_due_on=current_date where id=current_setting('body_test.fulld5')::uuid$$,'42501',null,'ordinary callers cannot rewrite schedule evidence');
select throws_ok($$update program_assignments set schedule_timezone='Europe/London' where id=current_setting('body_test.a')::uuid$$,'42501',null,'assignment timezone is protected');
select throws_ok($$update program_assignments set schedule_origin_rotation=100 where id=current_setting('body_test.a')::uuid$$,'42501',null,'derived rotation origin is protected');
reset role;
-- A reviewed historical correction reopens the real gap without inventing completion.
update workout_sets set deleted_at=clock_timestamp() where workout_exercise_id in(select id from workout_exercises where workout_session_id=current_setting('body_test.fulld3')::uuid);
set local role authenticated;
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,3,'historical correction reopens actual missing position');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'completedRotations')::int,0,'correction cannot leave a fabricated completed rotation');
select set_config('request.jwt.claims',json_build_object('sub',md5('schedule_b')::uuid,'role','authenticated')::text,true);
select is(program_schedule(current_setting('body_test.a')::uuid),null::jsonb,'foreign assignment calendar is private');
select is(program_schedule_cursor(current_setting('body_test.a')::uuid),null::jsonb,'foreign cursor is private');
select is((select count(*)::int from program_schedule_facts(current_setting('body_test.a')::uuid)),0,'foreign scheduling evidence is private');
select throws_ok($$select configure_program_schedule(current_setting('body_test.a')::uuid,current_date,'UTC',md5('foreign_config')::uuid)$$,'42501',null,'foreign configuration denied');
select set_config('request.jwt.claims',json_build_object('sub',md5('schedule_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.v4',pg_temp.rotation(4)::text,true);
select pg_temp.enroll(current_setting('body_test.v4')::uuid);
select set_config('body_test.w4',pg_temp.finish_day(current_setting('body_test.v4')::uuid,1,'schedule_4')::text,true);
select is(program_schedule()->>'configured','true','new assignments automatically use confirmed preference');
select is(program_schedule()->>'timezone','UTC','confirmed timezone persisted on assignment');
select is((program_schedule()->>'startDate')::date,current_date,'new schedule has server-derived local start date');
select is((program_schedule_cursor((program_adherence()->>'assignmentId')::uuid)->>'position')::int,3,'four-day rotation retains prescribed rest');
select ok(jsonb_array_length(program_schedule(null,current_date+90,31)->'events')>0,'distant monthly window uses bounded cycle jump');
select ok(not exists(select 1 from jsonb_array_elements(program_schedule(null,current_date+90,31)->'events')e where e->>'status'='overdue'),'future scheduled dates never receive premature overdue warnings');
select is(program_schedule(current_setting('body_test.a')::uuid)->>'state','completed','genuinely completed assignment retains truthful terminal completion');
select ok(jsonb_array_length(program_schedule(current_setting('body_test.a')::uuid,current_date-20,21)->'events')>0,'archived original due dates and actual history remain readable');
select ok(not exists(select 1 from jsonb_array_elements(program_schedule(current_setting('body_test.a')::uuid,current_date+1,7)->'events')),'archived assignment has no future prescription');
select throws_ok($$update program_assignments set ended_at=clock_timestamp()+interval '1 day' where id=current_setting('body_test.a')::uuid$$,'42501',null,'archived schedule boundary cannot be rewritten');
select set_config('body_test.v8',pg_temp.rotation(8)::text,true);
select pg_temp.enroll(current_setting('body_test.v8')::uuid);
select set_config('body_test.w8',pg_temp.finish_day(current_setting('body_test.v8')::uuid,1,'schedule_8')::text,true);
select is((program_schedule()->'next'->>'position')::int,3,'eight-day cycle preserves its next training position');
select set_config('body_test.v10',pg_temp.rotation(10)::text,true);
select pg_temp.enroll(current_setting('body_test.v10')::uuid);
select set_config('body_test.w10',pg_temp.finish_day(current_setting('body_test.v10')::uuid,1,'schedule_10')::text,true);
select is((program_schedule()->'next'->>'position')::int,3,'ten-day cycle is independent of weekdays');
select set_config('body_test.a10',program_schedule()->>'assignmentId',true);
select is((select cycle_length::int from program_assignments where id=current_setting('body_test.a10')::uuid),10,'ten-position identity remains explicit');
update account_preferences set scheduling_timezone='America/New_York' where owner_id=auth.uid();
select is(program_schedule()->>'timezone','UTC','changing preference never rewrites active assignment timezone');
select set_config('body_test.vny',pg_temp.rotation(3)::text,true);
select pg_temp.enroll(current_setting('body_test.vny')::uuid);
select set_config('body_test.wny',pg_temp.finish_day(current_setting('body_test.vny')::uuid,1,'schedule_ny')::text,true);
select set_config('body_test.any',program_schedule()->>'assignmentId',true);
select is(program_schedule()->>'timezone','America/New_York','new assignment uses deliberately changed timezone');
reset role;
update program_assignments set schedule_start_date=current_date-10 where id=current_setting('body_test.any')::uuid;
update workout_sessions set started_at=(current_date-1)::timestamp+interval '23 hours',finished_at=current_date::timestamp+interval '1 hour',effective_finished_at=current_date::timestamp+interval '1 hour',schedule_due_on=current_date-10 where id=current_setting('body_test.wny')::uuid;
set local role authenticated;
select is((select closed_on from program_schedule_facts(current_setting('body_test.any')::uuid) where session_id=current_setting('body_test.wny')::uuid),current_date-1,'cross-midnight completion uses persisted timezone, not UTC date');
reset role;
update program_assignments set schedule_start_date='2026-03-06' where id=current_setting('body_test.any')::uuid;
update workout_sessions set started_at='2026-03-08T06:30:00Z',finished_at='2026-03-08T07:30:00Z',effective_finished_at='2026-03-08T07:30:00Z',schedule_due_on='2026-03-06' where id=current_setting('body_test.wny')::uuid;
set local role authenticated;
select is((select closed_on from program_schedule_facts(current_setting('body_test.any')::uuid) where session_id=current_setting('body_test.wny')::uuid),'2026-03-08'::date,'spring DST completion uses local calendar date');
select is((program_schedule_cursor(current_setting('body_test.any')::uuid)->>'readyOn')::date,'2026-03-10'::date,'recovery uses calendar days across spring DST');
reset role;
update program_assignments set schedule_start_date='2026-10-30' where id=current_setting('body_test.any')::uuid;
update workout_sessions set started_at='2026-11-01T05:30:00Z',finished_at='2026-11-01T06:30:00Z',effective_finished_at='2026-11-01T06:30:00Z',schedule_due_on='2026-10-30' where id=current_setting('body_test.wny')::uuid;
set local role authenticated;
select is((select closed_on from program_schedule_facts(current_setting('body_test.any')::uuid) where session_id=current_setting('body_test.wny')::uuid),'2026-11-01'::date,'fall repeated hour has one deterministic calendar date');
select is((program_schedule_cursor(current_setting('body_test.any')::uuid)->>'readyOn')::date,'2026-11-03'::date,'fall DST does not add a duplicate recovery day');
select lives_ok($$select program_schedule(null,'2026-12-28',14)$$,'year boundary window remains valid');
select is(program_schedule(null,'2026-12-28',14),program_schedule(null,'2026-12-28',14),'year/month/week projection is stable across reads');
select ok(not has_function_privilege(r,'public.program_schedule(uuid,date,integer)','EXECUTE'),'calendar RPC denied to '||r) from unnest(array['anon','service_role'])r;
select ok(not has_function_privilege(r,'public.configure_program_schedule(uuid,date,text,uuid)','EXECUTE'),'configuration denied to '||r) from unnest(array['anon','service_role'])r;
select ok(not has_column_privilege('authenticated','public.program_assignments',c,'UPDATE'),'protected assignment field '||c) from unnest(array['schedule_start_date','schedule_timezone','schedule_origin_position','schedule_origin_rotation','schedule_initialized_at','schedule_first_session_id'])c;
select ok(not has_column_privilege('authenticated','public.workout_sessions','schedule_due_on','INSERT'),'cannot fabricate schedule history at start');

select set_config('body_test.vmroot',(select program_id::text from program_versions where id=current_setting('body_test.vny')::uuid),true);
update program_days set minimum_rest_hours=96 where program_id=current_setting('body_test.vmroot')::uuid and cycle_position=1;
select set_config('body_test.vmin',snapshot_program(current_setting('body_test.vmroot')::uuid)::text,true);
select pg_temp.enroll(current_setting('body_test.vmin')::uuid);
select set_config('body_test.wmin',pg_temp.finish_day(current_setting('body_test.vmin')::uuid,1,'minimum_rest')::text,true);
select is((program_schedule()->'next'->>'readyOn')::date,(program_schedule()->>'today')::date+4,'minimum rest hours conservatively expand full calendar-day spacing');
select ok(exists(select 1 from jsonb_array_elements(program_schedule(null,(program_schedule()->>'today')::date,7)->'events')e where e->>'status'='recovery'),'additional minimum-rest days are labeled recovery, not repeated program positions');
select ok(not exists(select 1 from jsonb_array_elements(program_schedule(null,(program_schedule()->>'today')::date,7)->'events')e where e->>'status'='recovery' and e ? 'position'),'extra recovery has no fabricated program day identity');

reset role;
update workout_sets set actual_reps=0 where workout_exercise_id in(select id from workout_exercises where workout_session_id=current_setting('body_test.wmin')::uuid);
set local role authenticated;
select is((program_schedule()->'next'->>'position')::int,1,'zero-repetition closed sets do not manufacture schedule progress');
reset role;
select throws_ok($$update workout_sets set inputs_confirmed=false where workout_exercise_id in(select id from workout_exercises where workout_session_id=current_setting('body_test.wmin')::uuid)$$,'23514',null,'completed unconfirmed evidence is structurally impossible');
set local role authenticated;
select is((program_schedule()->'next'->>'position')::int,1,'unconfirmed actuals never resolve a prescribed position');
select set_config('body_test.paused',start_program_workout(current_setting('body_test.vmin')::uuid,1,md5('schedule_pause')::uuid)::text,true);
select lives_ok($$select set_workout_pause(current_setting('body_test.paused')::uuid,true,0,md5('schedule_pause_command')::uuid)$$,'manual workout pause remains independent from scheduling');
select is((program_schedule()->'next'->>'position')::int,1,'manual pause and passive views cannot advance a program');
select end_workout(current_setting('body_test.paused')::uuid,'abandoned');
select is((program_schedule()->'next'->>'position')::int,1,'abandoned scheduled retry preserves pending position');
select * from finish();rollback;
